# Surah Yusuf (chapter 12) — part 10: ayat 91-100 (IDs 1687-1696)
SURAH = 12

ENTRIES = {
1687: (
"انہوں نے کہا — اللہ کی قسم — یقیناً — اللہ نے آپؑ کو ہم پر ترجیح دی — اور بے شک ہم خطاکار تھے",
"""۱۔ بھائی — یوسفؑ کی فضیلت کا اقرار کرتے ہیں۔
۲۔ ’’قَالُوا تَاللَّهِ لَقَدْ آثَرَكَ اللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَاطِئِينَ‘‘ — انہوں نے کہا — اللہ کی قسم — یقیناً — اللہ نے آپؑ کو ہم پر ترجیح دی — اور بے شک ہم خطاکار تھے — یعنی انہوں نے کہا — اللہ کی قسم — یقیناً اللہ نے آپ کو ہم پر ترجیح دی — اور بے شک ہم خطاکار تھے۔
۳۔ عملی سبق: خطا کا اقرار — ندامت کا پہلا قدم ہے۔"""
),
1688: (
"یوسفؑ نے کہا — آج کے دن تم پر کوئی ملامت نہیں — اللہ تمہاری مغفرت کرے — اور وہ سب سے زیادہ رحم کرنے والا ہے",
"""۱۔ یوسفؑ — عظیم عفو — کا مظاہرہ کرتے ہیں؛ ملامت نہیں۔
۲۔ ’’قَالَ لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْمَ يَغْفِرُ اللَّهُ لَكُمْ وَهُوَ أَرْحَمُ الرَّاحِمِينَ‘‘ — یوسفؑ نے کہا — آج کے دن تم پر کوئی ملامت نہیں — اللہ تمہاری مغفرت کرے — اور وہ سب سے زیادہ رحم کرنے والا ہے — یعنی یوسفؑ نے کہا — آج کے دن تم پر کوئی ملامت نہیں — اللہ تمہاری مغفرت کرے — اور وہ سب سے زیادہ رحم کرنے والا ہے۔
۳۔ عملی سبق: عفو و کرم — بڑے لوگوں کی صفت ہے۔"""
),
1689: (
"میری — یہ — قمیص — لے جاؤ — اور — اسے اپنے باپ کے چہرے پر ڈالو — وہ بینا ہو جائیں گے — اور اپنے — سب گھر والوں — کو — میرے پاس لے آؤ",
"""۱۔ یوسفؑ — قمیص مصر سے بھیجتے ہیں؛ باپ کی بصیرت کی بحالی کا وسیلہ۔
۲۔ ’’اذْهَبُوا بِقَمِيصِي هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِي يَأْتِ بَصِيرًا وَأْتُونِي بِأَهْلِكُمْ أَجْمَعِينَ‘‘ — میری — یہ — قمیص — لے جاؤ — اور — اسے اپنے باپ کے چہرے پر ڈالو — وہ بینا ہو جائیں گے — اور اپنے — سب گھر والوں — کو — میرے پاس لے آؤ — یعنی یوسفؑ نے کہا — میری یہ قمیص لے جاؤ — اور اسے میرے باپ کے چہرے پر ڈالو — وہ بینا ہو جائیں گے — اور اپنے سب اہل و عیال میرے پاس لے آؤ۔
۳۔ عملی سبق: اللہ بعض اوقات — بظاہر — معمولی چیزوں — میں — بڑا — شفا دیتا ہے۔"""
),
1690: (
"اور — جب — قافلہ — الگ ہوا — یعقوبؑ — نے کہا — بے شک — میں — یوسفؑ کی خوشبو سونگھ رہا ہوں — اگر تم مجھے بیوقوف — نہ سمجھو",
"""۱۔ قافلے — کے — روانہ ہوتے ہی یعقوبؑ — کو یوسفؑ کی خوشبو آنے لگی۔
۲۔ ’’وَلَمَّا فَصَلَتِ الْعِيرُ قَالَ أَبُوهُمْ إِنِّي لَأَجِدُ رِيحَ يُوسُفَ لَوْلَا أَن تُفَنِّدُونِ‘‘ — اور — جب — قافلہ — الگ ہوا — یعقوبؑ — نے کہا — بے شک — میں — یوسفؑ کی خوشبو سونگھ رہا ہوں — اگر تم مجھے بیوقوف — نہ سمجھو — یعنی جب قافلہ الگ ہوا تو ان کے باپ نے کہا — بے شک میں یوسفؑ کی خوشبو سونگھ رہا ہوں — اگر تم مجھے بے وقوف نہ سمجھو۔
۳۔ عملی سبق: سچے بندے کی روحانیت — دور سے بھی — حقیقت کو پالیتی ہے۔"""
),
1691: (
"انہوں نے کہا — اللہ کی قسم — بے شک آپ — اپنی پرانی گمراہی — میں — ہی ہیں",
"""۱۔ بیٹے — یعقوبؑ کی بات کو — نارمل دکھانے کی کوشش کرتے ہیں۔
۲۔ ’’قَالُوا تَاللَّهِ إِنَّكَ لَفِي ضَلَالِكَ الْقَدِيمِ‘‘ — انہوں نے کہا — اللہ کی قسم — بے شک آپ — اپنی پرانی گمراہی — میں — ہی ہیں — یعنی انہوں نے کہا — اللہ کی قسم — بے شک آپ اپنی پرانی گمراہی میں ہی ہیں۔
۳۔ عملی سبق: اللہ کے بندے کی حالت — کا اندازہ — دنیاوی لوگ نہیں کر سکتے۔"""
),
1692: (
"پس — جب — خوشخبری دینے والا — آیا — اور — اس نے — وہ — قمیص — یعقوبؑ کے چہرے پر ڈالی — یعقوبؑ — دوبارہ بینا ہوگئے — انہوں نے کہا — کیا میں تم سے نہیں کہتا تھا کہ میں اللہ کی طرف سے وہ جانتا ہوں جو تم نہیں جانتے",
"""۱۔ خوشخبری دینے والے — کے آنے پر — یعقوبؑ کی بصیرت واپس آ گئی۔
۲۔ ’’فَلَمَّا أَن جَاءَ الْبَشِيرُ أَلْقَاهُ عَلَىٰ وَجْهِهِ فَارْتَدَّ بَصِيرًا قَالَ أَلَمْ أَقُلْ لَّكُمْ إِنِّي أَعْلَمُ مِنَ اللَّهِ مَا لَا تَعْلَمُونَ‘‘ — پس — جب — خوشخبری دینے والا — آیا — اور — اس نے — وہ — قمیص — یعقوبؑ کے چہرے پر ڈالی — یعقوبؑ — دوبارہ بینا ہوگئے — انہوں نے کہا — کیا میں تم سے نہیں کہتا تھا کہ میں اللہ کی طرف سے وہ جانتا ہوں جو تم نہیں جانتے — یعنی پس جب خوشخبری دینے والا آیا — اور اس نے وہ قمیص ان کے چہرے پر ڈالی — وہ دوبارہ بینا ہوگئے — یعقوبؑ نے فرمایا — کیا میں نے تم سے نہیں کہا تھا کہ میں اللہ کی طرف سے وہ جانتا ہوں جو تم نہیں جانتے۔
۳۔ عملی سبق: اللہ کا وعدہ — بہترین وقت پر — پورا ہوتا ہے۔"""
),
1693: (
"انہوں نے کہا — اے ہمارے ابا — ہمارے لیے — ہماری گناہوں کی مغفرت — اللہ سے مانگ لیجیے — بے شک ہم خطاکار تھے",
"""۱۔ بیٹے — یعقوبؑ سے — اپنے گناہوں کی معافی کی درخواست کرتے ہیں۔
۲۔ ’’قَالُوا يَا أَبَانَا اسْتَغْفِرْ لَنَا ذُنُوبَنَا إِنَّا كُنَّا خَاطِئِينَ‘‘ — انہوں نے کہا — اے ہمارے ابا — ہمارے لیے — ہماری گناہوں کی مغفرت — اللہ سے مانگ لیجیے — بے شک ہم خطاکار تھے — یعنی انہوں نے کہا — اے ہمارے باپ — ہمارے گناہوں کی مغفرت مانگ لیجیے — بے شک ہم خطاکار تھے۔
۳۔ عملی سبق: بڑوں سے معافی مانگنا — نیز اللہ سے توبہ کرنا — کمال ہے۔"""
),
1694: (
"انہوں نے کہا — میں — عنقریب — اپنے رب سے — تمہارے لیے مغفرت مانگوں گا — بے شک وہ — غفور رحیم — ہے",
"""۱۔ یعقوبؑ — مقررہ وقت پر مغفرت کی طلب کریں گے — یا توبہ قبول ہوتی نظر آئے گی۔
۲۔ ’’قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّي إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ‘‘ — انہوں نے کہا — میں — عنقریب — اپنے رب سے — تمہارے لیے مغفرت مانگوں گا — بے شک وہ — غفور رحیم — ہے — یعنی یعقوبؑ نے کہا — میں عنقریب اپنے رب سے تمہارے لیے مغفرت مانگوں گا — بے شک وہ غفور رحیم ہے۔
۳۔ عملی سبق: توبہ کی قبولیت — میں اللہ کی مرضی کا انتظار — کرنا چاہیے۔"""
),
1695: (
"پس — جب — وہ — یوسفؑ کے پاس داخل ہوئے — اس — نے — اپنے ماں باپ — کو — اپنی طرف جگہ دی — اور کہا — مصر میں داخل ہو جایئے — ان شاء اللہ — امن و امان کے ساتھ",
"""۱۔ تمام اہلِ خاندان — مصر — میں آکر — یوسفؑ کے پاس جگہ پا گئے۔
۲۔ ’’فَلَمَّا دَخَلُوا عَلَىٰ يُوسُفَ آوَىٰ إِلَيْهِ أَبَوَيْهِ وَقَالَ ادْخُلُوا مِصْرَ إِن شَاءَ اللَّهُ آمِنِينَ‘‘ — پس — جب — وہ — یوسفؑ کے پاس داخل ہوئے — اس — نے — اپنے ماں باپ — کو — اپنی طرف جگہ دی — اور کہا — مصر میں داخل ہو جایئے — ان شاء اللہ — امن و امان کے ساتھ — یعنی پس جب وہ یوسفؑ کے پاس داخل ہوئے — یوسفؑ نے اپنے ماں باپ کو اپنی طرف جگہ دی — اور کہا — مصر میں داخل ہو جایئے ان شاء اللہ امن وامان کے ساتھ۔
۳۔ عملی سبق: اللہ کی رحمت — انجامِ کار — اہل یقین کو — سکون دیتی ہے۔"""
),
1696: (
"اور — یوسفؑ نے اپنے ماں باپ — کو — تخت پر بٹھایا — اور سب اس کے لیے — سجدہ ریز ہوئے — اور یوسفؑ نے کہا — اے میرے ابا — یہ ہے تعبیر — میرے اس خواب کی جو میں نے پہلے دیکھا تھا — اللہ نے اسے سچ کر دکھایا — اور اس نے مجھ پر احسان فرمایا کہ — مجھے جیل سے نکالا — اور آپ سب کو — صحرا سے — لے آیا — اس کے بعد کہ — شیطان نے — میرے اور میرے بھائیوں کے درمیان — فساد ڈال دیا — بے شک میرا رب — جس چیز کے لیے چاہتا ہے — لطیف ہے — بے شک وہ — علیم حکیم — ہے",
"""۱۔ یوسفؑ کا خواب — ساٹھ سال بعد — تعبیر ہوا؛ والدین اور بھائیوں کو تخت پر جگہ دی گئی؛ بڑے ادب سے احترام — کا اظہار کیا گیا (سجدہ تحیت تھا)۔
۲۔ ’’وَرَفَعَ أَبَوَيْهِ عَلَى الْعَرْشِ وَخَرُّوا لَهُ سُجَّدًا وَقَالَ يَا أَبَتِ هَٰذَا تَأْوِيلُ رُؤْيَايَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّي حَقًّا وَقَدْ أَحْسَنَ بِي إِذْ أَخْرَجَنِي مِنَ السِّجْنِ وَجَاءَ بِكُم مِّنَ الْبَدْوِ مِن بَعْدِ أَن نَّزَغَ الشَّيْطَانُ بَيْنِي وَبَيْنَ إِخْوَتِي إِنَّ رَبِّي لَطِيفٌ لِّمَا يَشَاءُ إِنَّهُ هُوَ الْعَلِيمُ الْحَكِيمُ‘‘ — اور — یوسفؑ نے اپنے ماں باپ — کو — تخت پر بٹھایا — اور سب اس کے لیے — سجدہ ریز ہوئے — اور یوسفؑ نے کہا — اے میرے ابا — یہ ہے تعبیر — میرے اس خواب کی جو میں نے پہلے دیکھا تھا — اللہ نے اسے سچ کر دکھایا — اور اس نے مجھ پر احسان فرمایا کہ — مجھے جیل سے نکالا — اور آپ سب کو — صحرا سے — لے آیا — اس کے بعد کہ — شیطان نے — میرے اور میرے بھائیوں کے درمیان — فساد ڈال دیا — بے شک میرا رب — جس چیز کے لیے چاہتا ہے — لطیف ہے — بے شک وہ — علیم حکیم — ہے — یعنی یوسفؑ نے اپنے ماں باپ کو تخت پر بٹھایا — اور سب اس کے لیے سجدہ ریز ہوگئے — یہ احترام کی علامت تھی، عبادت کا سجدہ نہیں — اور یوسفؑ نے کہا — اے میرے باپ — یہ ہے تعبیر میرے اس خواب کی جو میں نے پہلے دیکھا تھا — اللہ نے اس کو سچ کر دکھایا — اور اس نے مجھ پر احسان فرمایا کہ مجھے جیل سے نکالا — اور آپ سب کو صحرا سے لے آیا — اس کے بعد کہ شیطان نے میرے اور میرے بھائیوں کے درمیان فساد ڈال دیا — بے شک میرا رب جس چیز کے لیے چاہتا ہے لطیف ہے — بے شک وہ علیم حکیم ہے۔
۳۔ عملی سبق: اللہ کے وعدوں پر صبر — کا صلہ ہمیشہ ملتا ہے — بشرط یہ کہ نیت خالص ہو۔"""
),
}
